    "ai-scam": ["اے آئی آواز کی نقل سے دھوکا","دھوکا جس میں مجرم اے آئی سے کسی کی آواز یا چہرے کی نقل کر کے رشتے داروں یا ملازموں سے پیسے بھجواتے ہیں۔","سوشل میڈیا ویڈیو کی چند سیکنڈ کی آواز سے کسی کی آواز کی نقل بن سکتی ہے۔ پیسوں کی ہر جلدی والی مانگ کو جانے پہچانے نمبر پر واپس فون کر کے یا ایسی بات پوچھ کر جانچیں جو صرف اصل شخص جانتا ہو۔","آپ کے “بیٹے” کی آواز میں فون: “ابو، میں مصیبت میں ہوں، ابھی ₹50,000 بھیجیں”، جو دراصل ٹھگ ہے۔"],
    "misinformation": ["غلط معلومات (جعلی خبر)","غلطی سے یا جان بوجھ کر پھیلائی گئی جھوٹی یا گمراہ کن معلومات؛ اے آئی نے اسے بنانا اور تیز کر دیا ہے۔","اے آئی بڑے پیمانے پر یقین دلانے والی جعلی خبریں، تصویریں اور تبصرے لکھ سکتی ہے۔ آگے بھیجنے سے پہلے دیکھیں کس نے شائع کیا، اصل ذریعہ ڈھونڈیں اور حقائق کی جانچ والی سائٹیں استعمال کریں۔","ایسے طوفان کے دوران، جو کبھی آیا ہی نہیں، WhatsApp پر پھیلی “ڈوبے ہوئے ہاوڑہ برج” کی اے آئی سے بنی تصویر۔"],
    "ai-ethics": ["اے آئی اخلاقیات (ذمہ دار اے آئی)","یہ سوچنا کہ اے آئی بنانے اور استعمال کرنے میں کیا درست ہے اور کیا غلط۔","اہم سوال: کیا یہ منصفانہ ہے؟ کیا یہ شفاف ہے؟ نقصان ہونے پر ذمہ دار کون؟ کیا یہ رازداری کا احترام کرتا ہے؟ اخلاقیات قوانین، کمپنی کے اصولوں اور ہمارے اپنے فیصلوں کی رہنمائی کرتی ہے۔","یہ طے کرنا کہ اسکول کو حاضری کے لیے چہرے کی پہچان استعمال کرنی چاہیے یا نہیں، سہولت کو بچوں کی رازداری کے مقابل تول کر۔"],
    "explainability": ["وضاحت پذیری (قابلِ وضاحت اے آئی)","یہ سمجھ پانا کہ اے آئی نظام نے کوئی خاص فیصلہ کیوں کیا۔","ڈیپ نیٹ ورک اکثر “بلیک باکس” ہوتے ہیں۔ وضاحت کرنے والی تکنیکیں دکھاتی ہیں کہ کن ان پٹ کا سب سے زیادہ اثر تھا، جو قرض، طب اور قانون میں بہت ضروری ہے۔","قرض کی ایپ کا کسان کو صرف “مسترد” نہیں بلکہ “دو EMI چھوٹنے کی وجہ سے مسترد” بتانا۔"],
    "alignment": ["الائنمنٹ (انسانی اقدار سے ہم آہنگی)","یہ یقینی بنانا کہ اے آئی نظام کے مقاصد اور برتاؤ وہی ہوں جو انسان واقعی چاہتے اور اہم سمجھتے ہیں۔","غلط سمت والا نظام ہدایات پر لفظ بہ لفظ مگر نقصان دہ عمل کر سکتا ہے، یا غلط مقصد کے پیچھے بھاگ سکتا ہے۔ الائنمنٹ کے کام میں RLHF، حفاظتی جانچ اور واضح اصول شامل ہیں۔","سیکھنے کے مقصد سے ہم آہنگ ہوم ورک بوٹ سیدھے جواب تھمانے کے بجائے اشارے دیتا ہے۔"],
    "guardrails": ["گارڈ ریلز (حفاظتی حدیں)","اصول اور فلٹر جو اے آئی کو نقصان دہ، غیر قانونی یا موضوع سے ہٹ کر کچھ بنانے سے روکتے ہیں۔","گارڈ ریلز ان پٹ اور آؤٹ پٹ میں تشدد، نجی ڈیٹا یا بغیر تنبیہ کے طبی مشورے جیسی چیزیں جانچتے ہیں۔ یہ مکمل نہیں ہوتے، اس لیے انسانی جانچ اب بھی ضروری ہے۔","بچوں کی کہانیوں والی ایپ پرتشدد منظر لکھنے سے انکار کرتی ہے، یا بینک کا بوٹ بینکنگ کے علاوہ کسی بات پر گفتگو سے انکار کرتا ہے۔"],
