    "ai-label": ["اے آئی مواد کا لیبل (واٹر مارک)","ایک نظر آنے والا ٹیگ یا چھپا واٹر مارک جو بتائے کہ تصویر، ویڈیو یا آواز اے آئی سے بنی یا بدلی گئی ہے۔","لیبل سے لوگ بناوٹی مواد پہچان پاتے ہیں۔ بھارت کے آئی ٹی قواعد اب پلیٹ فارمز سے اے آئی سے بنے مواد پر لیبل لگانے کو کہتے ہیں، اور SynthID اور C2PA جیسے ٹولز چھپے نشان جوڑتے ہیں۔","کچھ Instagram ریلز کے نیچے “AI-generated” ٹیگ، یا اے آئی تصویر کے کونے میں چھوٹا واٹر مارک۔"],
    "copyright": ["کاپی رائٹ اور اے آئی","تخلیق کاروں کا اپنے کام پر قانونی حق؛ اے آئی اس پر تربیت اور اے آئی سے بنے کام کی ملکیت کے بارے میں سوال اٹھاتی ہے۔","عدالتیں اور حکومتیں ابھی طے کر رہی ہیں کہ کاپی رائٹ والی کتابوں، فن اور موسیقی پر تربیت کے لیے اجازت چاہیے یا نہیں، اور اے آئی سے بنی چیز کا مالک کون ہے۔ ذرائع کا حوالہ دیں اور تجارتی استعمال سے پہلے ٹول کی شرائط پڑھیں۔","کسی موسیقار کے گانوں سے بغیر اجازت موسیقی بنانے والا ٹول تربیت دینا، یا طالب علم کا اے آئی سے لکھے مضمون کا پورا کریڈٹ خود لینا۔"],
    "ai-detector": ["اے آئی ڈیٹیکٹر","ایک ٹول جو اندازہ لگانے کی کوشش کرتا ہے کہ تحریر یا تصویر اے آئی نے بنائی یا نہیں؛ اکثر قابلِ بھروسا نہیں۔","ڈیٹیکٹر بہت غلطیاں کرتے ہیں: یہ انسان کی تحریر کو (خاص طور پر جن کی مادری زبان انگریزی نہیں) اے آئی بتا سکتے ہیں اور اصل اے آئی تحریر چھوڑ سکتے ہیں۔ اساتذہ کو صرف ان پر بھروسا نہیں کرنا چاہیے۔","ایک ڈیٹیکٹر کسی طالبہ کے اپنے ایماندار مضمون کو “90% AI” بتا دیتا ہے، کیونکہ وہ سادہ، رسمی انگریزی لکھتی ہے۔"],
    "ai-literacy": ["اے آئی خواندگی","یہ جاننا کہ اے آئی کیا کر سکتی ہے اور کیا نہیں، اسے اچھی طرح کیسے استعمال کریں اور اس کے ساتھ محفوظ کیسے رہیں۔","پڑھنے لکھنے کی طرح اے آئی خواندگی اب طلبہ، اساتذہ، دکانداروں اور افسروں کے لیے بنیادی ہنر ہے۔ اس میں پرامپٹ لکھنا، حقائق جانچنا اور تعصب اور رازداری کو سمجھنا شامل ہے۔","ایک استانی اے آئی سے سبق کے منصوبے کا مسودہ بنواتی ہیں، پھر حقائق جانچ کر اسے اپنے طلبہ کے لحاظ سے ڈھالتی ہیں: سمجھ داری سے استعمال، اندھا بھروسا نہیں۔"],
    "data-scientist": ["ڈیٹا سائنٹسٹ (ڈیٹا سائنس دان)","ایک ماہر جو ڈیٹا جمع کرتا، صاف کرتا، اس کا تجزیہ کرتا اور سوالوں کے جواب کے لیے ماڈل بناتا ہے۔","وہ شماریات، پروگرامنگ (عام طور پر Python) اور اپنے شعبے کی معلومات کو ملاتے ہیں۔ بھارت میں دنیا کی سب سے بڑی ڈیٹا سائنس افرادی قوتوں میں سے ایک ہے۔","ایک فوڈ ڈلیوری کمپنی کا ڈیٹا سائنٹسٹ معلوم کرتا ہے کہ جے پور میں منگل کی شام آرڈر کیوں گھٹتے ہیں۔"],
    "ml-engineer": ["مشین لرننگ انجینئر (ایم ایل آپس)","ایک انجینئر جو ماڈلوں کو لاکھوں صارفین کے لیے چلنے والے قابلِ بھروسا سافٹ ویئر میں بدلتا ہے۔","وہ تربیتی پائپ لائن، تعیناتی، رفتار، لاگت اور نگرانی سنبھالتے ہیں (اسے ایم ایل آپس بھی کہتے ہیں)۔ مضبوط کوڈنگ اور نظام کا ہنر اتنا ہی ضروری ہے جتنا حساب۔","یہ یقینی بنانا کہ UPI دھوکا دہی کا ماڈل دن رات ہر ادائیگی پر 100 ملی سیکنڈ سے کم میں جواب دے۔"],
    "prompt-engineer": ["پرامپٹ انجینئر (کام میں اے آئی ہنر)","اے آئی ٹولز سے بہترین نتائج نکالنے میں ماہر شخص؛ اب یہ الگ نوکری کم اور سب کے لیے ضروری ہنر زیادہ ہے۔","شروع میں کمپنیوں نے پرامپٹ انجینئر رکھے۔ اب مارکیٹنگ سے لے کر تدریس تک زیادہ تر کرداروں میں لوگوں سے اے آئی کو اچھی طرح استعمال کرنے کی توقع ہے۔ صاف سوچ اور اپنے شعبے کا علم سب سے زیادہ اہم ہے۔","اندور کا ایک کانٹینٹ رائٹر اے آئی سے ایک گھنٹے میں 10 مصنوعات کی تفصیلات کا مسودہ بناتا ہے اور انہیں درستی اور لہجے کے لیے سنوارتا ہے۔"],
